33	static const char* TAG = "netmgr";
34	
35	static char s_ip_str[INET_ADDRSTRLEN] = "0.0.0.0";
36	
37	bool network_is_connected(void)
38	{
39	    struct ifaddrs* ifa_list = NULL;
40	    if (getifaddrs(&ifa_list) == 0) {
41	        for (struct ifaddrs* ifa = ifa_list; ifa; ifa = ifa->ifa_next) {
42	            if (!ifa->ifa_addr)
43	                continue;
44	            if (ifa->ifa_addr->sa_family != AF_INET)
45	                continue;
46	            if (ifa->ifa_name && strncmp(ifa->ifa_name, "lo", 2) == 0)
47	                continue;
48	
49	            struct sockaddr_in* sin = (struct sockaddr_in*)ifa->ifa_addr;
50	            uint32_t addr = ntohl(sin->sin_addr.s_addr);
51	            if ((addr >> 24) == 127)
52	                continue; /* 127.x.x.x loopback */
53	
54	            /* Skip 0.0.0.0 — interface exists but has no IP yet */
55	            if (addr == 0)
56	                continue;
57	
58	            inet_ntop(AF_INET, &sin->sin_addr, s_ip_str, sizeof(s_ip_str));
59	            syslog(LOG_INFO, "[%s] Found iface %s addr %s\n", TAG,
60	                ifa->ifa_name ? ifa->ifa_name : "?", s_ip_str);
61	            freeifaddrs(ifa_list);
62	            return true;
63	        }
64	        freeifaddrs(ifa_list);
65	    }
66	
67	    return false;
68	}
