70	int network_wait_connected(uint32_t timeout_ms)
71	{
72	    if (timeout_ms == 0) {
73	        return network_is_connected() ? OK : ERROR;
74	    }
75	
76	    struct timespec deadline;
77	    clock_gettime(CLOCK_REALTIME, &deadline);
78	    deadline.tv_sec += (time_t)(timeout_ms / 1000);
79	    deadline.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
80	    if (deadline.tv_nsec >= 1000000000L) {
81	        deadline.tv_sec++;
82	        deadline.tv_nsec -= 1000000000L;
83	    }
84	
85	    while (1) {
86	        if (network_is_connected()) {
87	            syslog(LOG_INFO, "[%s] Network connected: %s\n", TAG, s_ip_str);
88	            return OK;
89	        }
90	
91	        struct timespec now;
92	        clock_gettime(CLOCK_REALTIME, &now);
93	        if (now.tv_sec > deadline.tv_sec || (now.tv_sec == deadline.tv_sec && now.tv_nsec >= deadline.tv_nsec)) {
94	            syslog(LOG_WARNING, "[%s] Timed out waiting for network\n", TAG);
95	            return ERROR;
96	        }
97	
98	        usleep(500000); /* poll every 500 ms */
99	    }
100	}
