108	int network_set_dns(const char* primary, const char* secondary)
109	{
110	    struct in_addr dns_addr;
111	    FILE* fp = NULL;
112	
113	    if (!primary || primary[0] == '\0') {
114	        syslog(LOG_ERR, "[%s] set_dns: primary DNS required\n", TAG);
115	        return -EINVAL;
116	    }
117	
118	    if (inet_pton(AF_INET, primary, &dns_addr) != 1
119	        || netlib_set_ipv4dnsaddr(&dns_addr) != OK) {
120	        syslog(LOG_ERR, "[%s] Invalid primary DNS: %s\n", TAG, primary);
121	        return -EINVAL;
122	    }
123	
124	    if (secondary && secondary[0] != '\0') {
125	        if (inet_pton(AF_INET, secondary, &dns_addr) != 1
126	            || netlib_set_ipv4dnsaddr(&dns_addr) != OK) {
127	            syslog(LOG_ERR, "[%s] Invalid secondary DNS: %s\n",
128	                TAG, secondary);
129	            return -EINVAL;
130	        }
131	    }
132	
133	    /* 同步写出诊断文件；实际解析器使用上面的 NuttX nameserver 列表。 */
134	    fp = fopen("/tmp/resolv.conf", "w");
135	    if (!fp) {
136	        syslog(LOG_ERR, "[%s] Cannot open /tmp/resolv.conf: %d\n",
137	            TAG, errno);
138	        return -errno;
139	    }
140	
141	    fprintf(fp, "nameserver %s\n", primary);
142	    if (secondary && secondary[0] != '\0') {
143	        fprintf(fp, "nameserver %s\n", secondary);
144	    }
145	
146	    fclose(fp);
147	
148	    claw_config_set("net.dns_primary", primary);
149	    if (secondary && secondary[0] != '\0') {
150	        claw_config_set("net.dns_secondary", secondary);
151	    }
152	
153	    syslog(LOG_INFO, "[%s] DNS configured: %s %s\n", TAG,
154	        primary, (secondary && secondary[0]) ? secondary : "");
155	    return OK;
156	}
