179	int network_wifi_reconnect(void)
180	{
181	    syslog(LOG_INFO, "[%s] QEMU: Initializing eth0...\n", TAG);
182	
183	    /* Bring up eth0 interface */
184	    int ret = system("ifup eth0");
185	    if (ret != 0) {
186	        syslog(LOG_WARNING, "[%s] ifup eth0 failed: %d\n", TAG, ret);
187	    }
188	
189	    /* Request DHCP lease */
190	    ret = system("renew eth0");
191	    if (ret != 0) {
192	        syslog(LOG_WARNING, "[%s] renew eth0 failed: %d\n", TAG, ret);
193	    }
194	
195	    /* Wait a bit for network to come up */
196	    usleep(500000);
197	
198	    return network_wait_connected(5000);
199	}
