241	static void notify_listeners(net_state_t state)
242	{
243	    for (int i = 0; i < g_listener_count; i++) {
244	        if (g_listeners[i].cb) {
245	            g_listeners[i].cb(state, g_listeners[i].arg);
246	        }
247	    }
248	}
