250	static void set_net_state(net_state_t new_state)
251	{
252	    pthread_mutex_lock(&g_net_mutex);
253	    if (g_net_status.state != new_state) {
254	        net_state_t old = g_net_status.state;
255	        g_net_status.state = new_state;
256	
257	        if (new_state == NET_STATE_CONNECTED) {
258	            g_net_status.connected_since = time(NULL);
259	        }
260	
261	        syslog(LOG_INFO, "[%s] State: %s -> %s\n", TAG,
262	            old == NET_STATE_CONNECTED ? "CONNECTED" : "DISCONNECTED",
263	            new_state == NET_STATE_CONNECTED ? "CONNECTED" : "DISCONNECTED");
264	
265	        notify_listeners(new_state);
266	        pthread_cond_broadcast(&g_net_cond);
267	    }
268	    pthread_mutex_unlock(&g_net_mutex);
269	}
