271	/**
272	 * Check network interfaces via getifaddrs().
273	 * Returns true if a valid non-loopback IPv4 interface is found.
274	 * Accepts rpmsg*, tun*, eth* etc. Skips lo* and 127.x.x.x / 0.0.0.0.
275	 */
276	static bool check_interfaces(void)
277	{
278	    struct ifaddrs* ifa_list = NULL;
279	    bool found = false;
280	
281	    if (getifaddrs(&ifa_list) != 0) {
282	        syslog(LOG_WARNING, "[%s] getifaddrs failed: %d\n", TAG, errno);
283	        return false;
284	    }
285	
286	    for (struct ifaddrs* ifa = ifa_list; ifa; ifa = ifa->ifa_next) {
287	        if (!ifa->ifa_addr) {
288	            continue;
289	        }
290	        if (ifa->ifa_addr->sa_family != AF_INET) {
291	            continue;
292	        }
293	        if (ifa->ifa_name && strncmp(ifa->ifa_name, "lo", 2) == 0) {
294	            continue;
295	        }
296	
297	        struct sockaddr_in* sin = (struct sockaddr_in*)ifa->ifa_addr;
298	        uint32_t addr = ntohl(sin->sin_addr.s_addr);
299	
300	        /* Skip 127.x.x.x loopback */
301	        if ((addr >> 24) == 127) {
302	            continue;
303	        }
304	        /* Skip 0.0.0.0 — interface exists but has no IP yet */
305	        if (addr == 0) {
306	            continue;
307	        }
308	
309	        /* Valid interface found */
310	        pthread_mutex_lock(&g_net_mutex);
311	        inet_ntop(AF_INET, &sin->sin_addr,
312	            g_net_status.ip_addr, sizeof(g_net_status.ip_addr));
313	        if (ifa->ifa_name) {
314	            strncpy(g_net_status.iface_name, ifa->ifa_name,
315	                sizeof(g_net_status.iface_name) - 1);
316	            g_net_status.iface_name[sizeof(g_net_status.iface_name) - 1] = '\0';
317	        }
318	        g_net_status.last_check = time(NULL);
319	        pthread_mutex_unlock(&g_net_mutex);
320	
321	        /* Also update the shared s_ip_str for network_get_ip() */
322	        inet_ntop(AF_INET, &sin->sin_addr, s_ip_str, sizeof(s_ip_str));
323	
324	        syslog(LOG_DEBUG, "[%s] Found iface %s addr %s\n", TAG,
325	            ifa->ifa_name ? ifa->ifa_name : "?",
326	            g_net_status.ip_addr);
327	
328	        found = true;
329	        break;
330	    }
331	
332	    freeifaddrs(ifa_list);
333	    return found;
334	}
