338	static void load_net_config(void)
339	{
340	    char buf[32] = { 0 };
341	
342	    /* proxy_mode: default "usrsock" */
343	    if (claw_config_get("net.proxy_mode", g_net_config.proxy_mode,
344	            sizeof(g_net_config.proxy_mode))
345	            != OK
346	        || g_net_config.proxy_mode[0] == '\0') {
347	        strncpy(g_net_config.proxy_mode, "usrsock",
348	            sizeof(g_net_config.proxy_mode) - 1);
349	        g_net_config.proxy_mode[sizeof(g_net_config.proxy_mode) - 1] = '\0';
350	    }
351	
352	    /* rpmsg_cpu: default "ap" */
353	    if (claw_config_get("net.rpmsg_cpu", g_net_config.rpmsg_cpu,
354	            sizeof(g_net_config.rpmsg_cpu))
355	            != OK
356	        || g_net_config.rpmsg_cpu[0] == '\0') {
357	        strncpy(g_net_config.rpmsg_cpu, "ap",
358	            sizeof(g_net_config.rpmsg_cpu) - 1);
359	        g_net_config.rpmsg_cpu[sizeof(g_net_config.rpmsg_cpu) - 1] = '\0';
360	    }
361	
362	    /* connect_timeout: default 15 */
363	    if (claw_config_get("net.connect_timeout", buf, sizeof(buf)) == OK
364	        && buf[0] != '\0') {
365	        g_net_config.connect_timeout = atoi(buf);
366	    } else {
367	        g_net_config.connect_timeout = 15;
368	    }
369	
370	    /* read_timeout: default 30 */
371	    memset(buf, 0, sizeof(buf));
372	    if (claw_config_get("net.read_timeout", buf, sizeof(buf)) == OK
373	        && buf[0] != '\0') {
374	        g_net_config.read_timeout = atoi(buf);
375	    } else {
376	        g_net_config.read_timeout = 30;
377	    }
378	
379	    /* retry_max: default 3 */
380	    memset(buf, 0, sizeof(buf));
381	    if (claw_config_get("net.retry_max", buf, sizeof(buf)) == OK
382	        && buf[0] != '\0') {
383	        g_net_config.retry_max = atoi(buf);
384	    } else {
385	        g_net_config.retry_max = 3;
386	    }
387	
388	    /* retry_base_sec: default 2 */
389	    memset(buf, 0, sizeof(buf));
390	    if (claw_config_get("net.retry_base_sec", buf, sizeof(buf)) == OK
391	        && buf[0] != '\0') {
392	        g_net_config.retry_base_sec = atoi(buf);
393	    } else {
394	        g_net_config.retry_base_sec = 2;
395	    }
396	
397	    syslog(LOG_INFO,
398	        "[%s] Config loaded: proxy=%s cpu=%s timeout=%d/%d retry=%d base=%d\n",
399	        TAG, g_net_config.proxy_mode, g_net_config.rpmsg_cpu,
400	        g_net_config.connect_timeout, g_net_config.read_timeout,
401	        g_net_config.retry_max, g_net_config.retry_base_sec);
402	}
