460	/* ── Interface poll thread ────────────────────────────────────── */
461	
462	static void* iface_poll_thread(void* arg)
463	{
464	    (void)arg;
465	    syslog(LOG_INFO, "[%s] O74I interface poll thread started\n", TAG);
466	
467	    /* Startup timeout: 30 seconds to get an IP */
468	    struct timespec start;
469	    clock_gettime(CLOCK_MONOTONIC, &start);
470	    bool startup_warned = false;
471	
472	    while (g_poll_running) {
473	        bool has_ip = check_interfaces();
474	
475	        if (has_ip) {
476	            set_net_state(NET_STATE_CONNECTED);
477	            startup_warned = false;
478	        } else {
479	            set_net_state(NET_STATE_DISCONNECTED);
480	
481	            /* Check startup timeout */
482	            if (!startup_warned) {
483	                struct timespec now;
484	                clock_gettime(CLOCK_MONOTONIC, &now);
485	                long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000L
486	                    + (now.tv_nsec - start.tv_nsec) / 1000000L;
487	                if (elapsed_ms >= NET_STARTUP_TIMEOUT_MS) {
488	                    syslog(LOG_WARNING,
489	                        "[%s] No IP after %d ms startup timeout, "
490	                        "continuing poll\n",
491	                        TAG, NET_STARTUP_TIMEOUT_MS);
492	                    startup_warned = true;
493	                }
494	            }
495	        }
496	
497	        /* Sleep for poll interval, but wake early on force check */
498	        struct timespec ts;
499	        clock_gettime(CLOCK_REALTIME, &ts);
500	        ts.tv_sec += NET_POLL_INTERVAL_MS / 1000;
501	        ts.tv_nsec += (NET_POLL_INTERVAL_MS % 1000) * 1000000L;
502	        if (ts.tv_nsec >= 1000000000L) {
503	            ts.tv_sec++;
504	            ts.tv_nsec -= 1000000000L;
505	        }
506	
507	        pthread_mutex_lock(&g_net_mutex);
508	        while (!g_force_check && g_poll_running) {
509	            int rc = pthread_cond_timedwait(&g_net_cond, &g_net_mutex, &ts);
510	            if (rc == ETIMEDOUT) {
511	                break;
512	            }
513	        }
514	        g_force_check = false;
515	        pthread_mutex_unlock(&g_net_mutex);
516	    }
517	
518	    syslog(LOG_INFO, "[%s] O74I interface poll thread exiting\n", TAG);
519	    return NULL;
520	}
