524	int network_register_listener(net_state_cb_t cb, void* arg)
525	{
526	    if (!cb) {
527	        return -EINVAL;
528	    }
529	
530	    pthread_mutex_lock(&g_net_mutex);
531	    if (g_listener_count >= NET_MAX_LISTENERS) {
532	        pthread_mutex_unlock(&g_net_mutex);
533	        syslog(LOG_ERR, "[%s] Max listeners (%d) reached\n",
534	            TAG, NET_MAX_LISTENERS);
535	        return -ENOMEM;
536	    }
537	
538	    g_listeners[g_listener_count].cb = cb;
539	    g_listeners[g_listener_count].arg = arg;
540	    g_listener_count++;
541	    pthread_mutex_unlock(&g_net_mutex);
542	
543	    return OK;
544	}
