564	int network_get_iob_usage(void)
565	{
566	    FILE* fp = NULL;
567	    int usage_pct = 0;
568	    char line[128];
569	    int total = 0;
570	    int free_cnt = 0;
571	
572	    fp = fopen("/proc/net/iob", "r");
573	    if (!fp) {
574	        syslog(LOG_DEBUG, "[%s] Cannot open /proc/net/iob\n", TAG);
575	        return 0;
576	    }
577	
578	    /* Parse IOB stats — look for total and free counts.
579	     * Format varies by NuttX version; try common patterns. */
580	    while (fgets(line, sizeof(line), fp)) {
581	        if (sscanf(line, "  total:%d", &total) == 1) {
582	            /* found total */
583	        } else if (sscanf(line, "  free:%d", &free_cnt) == 1) {
584	            /* found free */
585	        }
586	    }
587	
588	    fclose(fp);
589	
590	    if (total > 0) {
591	        usage_pct = ((total - free_cnt) * 100) / total;
592	        if (usage_pct < 0) {
593	            usage_pct = 0;
594	        }
595	        if (usage_pct > 100) {
596	            usage_pct = 100;
597	        }
598	    }
599	
600	    pthread_mutex_lock(&g_net_mutex);
601	    g_net_status.iob_usage_pct = usage_pct;
602	    pthread_mutex_unlock(&g_net_mutex);
603	
604	    return usage_pct;
605	}
