718	
719	    /* Fast-fail if BLE is disconnected */
720	    if (!g_net_status.ble_connected) {
721	        pthread_mutex_unlock(&g_net_mutex);
722	        return -ENETUNREACH;
723	    }
724	
725	    /* Check TCP connection limit and IOB watermark */
726	    struct timespec deadline;
727	    clock_gettime(CLOCK_REALTIME, &deadline);
728	    deadline.tv_sec += (time_t)(timeout_ms / 1000);
729	    deadline.tv_nsec += (long)((timeout_ms % 1000) * 1000000L);
730	    if (deadline.tv_nsec >= 1000000000L) {
731	        deadline.tv_sec++;
732	        deadline.tv_nsec -= 1000000000L;
733	    }
734	
735	    while (g_net_status.active_conns >= NET_MAX_TCP_CONNS
736	        || network_get_iob_usage() >= NET_IOB_HIGH_WATERMARK) {
737	        int rc = pthread_cond_timedwait(&g_net_cond, &g_net_mutex, &deadline);
738	        if (rc == ETIMEDOUT) {
739	            pthread_mutex_unlock(&g_net_mutex);
740	            syslog(LOG_WARNING, "[%s] acquire_resource timeout\n", TAG);
741	            return -ETIMEDOUT;
742	        }
743	        /* Re-check BLE after wakeup */
744	        if (!g_net_status.ble_connected) {
745	            pthread_mutex_unlock(&g_net_mutex);
746	            return -ENETUNREACH;
747	        }
748	    }
749	
750	    g_net_status.active_conns++;
751	    pthread_mutex_unlock(&g_net_mutex);
752	    return OK;
