#!/usr/bin/env python3
# 持久串口桥：从 stdin 读入的每一行写到串口（追加 CRLF）；串口输出实时打到 stdout。
# 供 Executor MCP 托管，实现对开发板 NSH/vela 的持续交互控制。
import serial
import sys
import threading

PORT = "/dev/cu.usbmodem101"
BAUD = 115200


def main():
    try:
        ser = serial.Serial(PORT, BAUD, timeout=0.1)
    except Exception as exc:
        sys.stdout.write(f"[串口桥] 打开串口失败：{exc}\n")
        sys.stdout.flush()
        return 1

    stop = threading.Event()

    def reader():
        while not stop.is_set():
            try:
                data = ser.read(4096)
            except Exception as exc:
                sys.stdout.write(f"\n[串口桥] 读错误：{exc}\n")
                sys.stdout.flush()
                break
            if data:
                sys.stdout.buffer.write(data)
                sys.stdout.buffer.flush()

    t = threading.Thread(target=reader, daemon=True)
    t.start()
    sys.stdout.write("[串口桥] 就绪，可发送命令\n")
    sys.stdout.flush()

    try:
        while True:
            line = sys.stdin.readline()
            if not line:
                break
            line = line.rstrip("\r\n")
            try:
                ser.write((line + "\r\n").encode("utf-8"))
            except Exception as exc:
                sys.stdout.write(f"\n[串口桥] 写错误：{exc}\n")
                sys.stdout.flush()
                break
    finally:
        stop.set()
        ser.close()
    return 0


if __name__ == "__main__":
    sys.exit(main())

