/*
 * 监控线程：每 5 秒检查一次关联状态，一旦掉线（BSSID 失效）就发起完整
 * 重连（ifdown/ifup + 关联 + DHCP）。ESP32-S3 的 STA_DISCONNECT 自动重连
 * 走 esp_wifi_connect 直连、不做接口重置，而首次握手失败需要 ifdown/ifup
 * 重置才能成功，故驱动层重连无法自愈；这里在应用层用完整流程兜底，保证
 * 掉线后网络能自动恢复。
 */
static void* wifi_monitor_thread(void* arg)
{
    (void)arg;
    while (s_wifi_monitor_running) {
        sleep(5);
        if (!s_wifi_monitor_running) {
            break;
        }
        /* 单次快速检查关联状态（BSSID 是否为真实 AP MAC）。 */
        if (!wifi_wait_associated(s_wifi_monitor_dev, 800)) {
            syslog(LOG_WARNING,
                "[%s] WiFi link lost, auto-reconnecting...\n", TAG);
            network_wifi_reconnect();
        }
    }
    return NULL;
}

